// Generated by Cube Creator.
// Add this component to the root of an imported Cube Creator model and assign
// CubeCreatorConfig.json. It recreates the idle animation, glow pulse, texture
// scrolling, particle layers and the click "squash + burst" feedback.
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

namespace CubeCreator
{
    [Serializable] public class ClickEvent : UnityEvent<int> { }

    [DisallowMultipleComponent]
    public class CubeCreatorCube : MonoBehaviour
    {
        [Tooltip("CubeCreatorConfig.json exported with the model")]
        public TextAsset config;
        public bool animate = true;
        public bool buildParticles = true;
        public bool applyGlow = true;
        [Tooltip("Adds a BoxCollider and reacts to OnMouseDown. With the new Input System only, call Click() yourself.")]
        public bool clickable = true;
        public ClickEvent onClicked = new ClickEvent();
        public int clicks;

        public static event Action<CubeCreatorCube> AnyCubeClicked;

        const float TAU = Mathf.PI * 2f;
        static readonly string[] EmissionProps = { "_EmissionColor", "emissiveFactor" };
        static readonly string[] TextureProps = { "_BaseMap", "_MainTex", "baseColorTexture", "_EmissionMap", "emissiveTexture", "_BumpMap", "normalTexture" };

        CubeConfig cfg;
        Transform pivot, spinner;
        Vector3 pivotPos, pivotScale;
        Quaternion spinnerRot;
        float angleX, angleY, time, squashX, squashV;
        ParticleSystem burst;
        readonly List<(Material mat, string prop, Color baseColor)> glow = new List<(Material, string, Color)>();
        readonly List<Material> scrollMats = new List<Material>();

        void Awake()
        {
            if (config == null)
            {
                Debug.LogWarning("[CubeCreator] No config assigned on " + name, this);
                return;
            }
            cfg = JsonUtility.FromJson<CubeConfig>(config.text);
            pivot = FindDeep(transform, "Pivot");
            if (pivot == null) pivot = transform;
            spinner = FindDeep(transform, "CubeMesh");
            if (spinner == null) spinner = pivot;
            pivotPos = pivot.localPosition;
            pivotScale = pivot.localScale;
            spinnerRot = spinner.localRotation;

            CollectMaterials();
            if (buildParticles) BuildParticles();
            if (clickable && GetComponent<Collider>() == null) AddCollider();
        }

        void CollectMaterials()
        {
            Color glowColor = ColorUtil.Parse(cfg.glow != null ? cfg.glow.color : null, Color.black);
            float glowIntensity = cfg.glow != null ? cfg.glow.intensity : 0f;
            foreach (var r in GetComponentsInChildren<Renderer>())
            {
                if (r is ParticleSystemRenderer) continue;
                foreach (var m in r.materials)
                {
                    foreach (var prop in EmissionProps)
                    {
                        if (!m.HasProperty(prop)) continue;
                        Color c = m.GetColor(prop);
                        // OBJ / non-glTF imports lose emission: restore it from the config
                        if (applyGlow && c.maxColorComponent < 0.001f && glowIntensity > 0f && m.name.Contains("CubeSurface"))
                        {
                            c = glowColor * glowIntensity;
                            m.SetColor(prop, c);
                            m.EnableKeyword("_EMISSION");
                            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.RealtimeEmissive;
                        }
                        glow.Add((m, prop, c));
                    }
                    scrollMats.Add(m);
                }
            }
        }

        void BuildParticles()
        {
            if (cfg.particles != null)
                foreach (var layer in cfg.particles)
                    CubeCreatorParticles.Build(layer, pivot, cfg.bounds, false);
            if (cfg.clicker != null && cfg.clicker.hasBurst && cfg.clicker.burst != null)
                burst = CubeCreatorParticles.Build(cfg.clicker.burst, pivot, cfg.bounds, true);
        }

        void AddCollider()
        {
            var renderers = GetComponentsInChildren<MeshRenderer>();
            if (renderers.Length == 0) return;
            Bounds b = renderers[0].bounds;
            foreach (var r in renderers) b.Encapsulate(r.bounds);
            var box = gameObject.AddComponent<BoxCollider>();
            box.center = transform.InverseTransformPoint(b.center);
            Vector3 s = transform.lossyScale;
            box.size = new Vector3(b.size.x / Mathf.Max(1e-5f, s.x), b.size.y / Mathf.Max(1e-5f, s.y), b.size.z / Mathf.Max(1e-5f, s.z));
        }

        void OnMouseDown()
        {
            if (clickable) Click();
        }

        /// Trigger the click feedback (squash, particle burst, events).
        public void Click()
        {
            clicks++;
            if (cfg != null && cfg.clicker != null && cfg.clicker.enabled)
            {
                squashV -= 30f * cfg.clicker.squash;
                if (burst != null)
                {
                    if (!burst.isPlaying) burst.Play();
                    burst.Emit(Mathf.Max(1, cfg.clicker.burstCount));
                }
            }
            onClicked.Invoke(clicks);
            AnyCubeClicked?.Invoke(this);
        }

        void Update()
        {
            if (cfg == null || cfg.animation == null || !animate) return;
            var a = cfg.animation;
            float dt = Time.deltaTime;
            time += dt;

            angleX += a.spinX * 90f * dt;
            angleY += a.spinY * 90f * dt;
            float wobble = a.wobble * 0.25f * Mathf.Sin(time * 1.7f) * Mathf.Rad2Deg;
            spinner.localRotation = spinnerRot * Quaternion.Euler(angleX, angleY, wobble);

            squashV += (-squashX * 260f - squashV * 14f) * dt;
            squashX += squashV * dt;
            float pulse = 1f + a.pulseScale * 0.5f * Mathf.Sin(time * a.pulseSpeed * TAU);
            float sx = pulse * (1f - squashX * 0.5f);
            float sy = pulse * (1f + squashX);
            pivot.localScale = Vector3.Scale(pivotScale, new Vector3(sx, sy, sx));
            pivot.localPosition = pivotPos + Vector3.up * (a.bobAmplitude * Mathf.Sin(time * a.bobSpeed * TAU));

            float k = 1f;
            if (a.glowPulse > 0f) k *= 1f - a.glowPulse * 0.5f + a.glowPulse * 0.5f * Mathf.Sin(time * a.glowPulseSpeed * TAU);
            if (a.flicker > 0f) k *= 1f - a.flicker * 0.5f * (Mathf.Sin(time * 23.1f) * Mathf.Sin(time * 13.7f) * 0.5f + 0.5f + UnityEngine.Random.value * 0.3f);
            if (a.glowPulse > 0f || a.flicker > 0f)
                foreach (var g in glow) g.mat.SetColor(g.prop, g.baseColor * k);

            if (a.scrollU != 0f || a.scrollV != 0f)
            {
                var offset = new Vector2(Mathf.Repeat(time * a.scrollU, 1f), Mathf.Repeat(time * a.scrollV, 1f));
                foreach (var m in scrollMats)
                    foreach (var prop in TextureProps)
                        if (m.HasProperty(prop)) m.SetTextureOffset(prop, offset);
            }
        }

        static Transform FindDeep(Transform t, string n)
        {
            if (t.name == n) return t;
            foreach (Transform c in t)
            {
                var r = FindDeep(c, n);
                if (r != null) return r;
            }
            return null;
        }
    }
}
